function validate([n, wells, pipes]) {
  if (!Number.isInteger(n) || n < 2 || n > 10000) return 'n is between 2 and 10000.';
  if (!Array.isArray(wells) || wells.length !== n) return 'wells needs exactly n costs.';
  if (wells.some(c => !Number.isInteger(c) || c < 0 || c > 100000)) return 'Each well cost is between 0 and 100000.';
  if (!Array.isArray(pipes) || pipes.length < 1 || pipes.length > 10000) return 'pipes needs 1 to 10000 entries.';
  for (const pipe of pipes) {
    if (!Array.isArray(pipe) || pipe.length !== 3 || !pipe.every(Number.isInteger)) return 'Each pipe is [house1, house2, cost].';
    const [house1, house2, cost] = pipe;
    if (house1 < 1 || house1 > n || house2 < 1 || house2 > n) return 'Pipe ends are houses 1 to n.';
    if (house1 === house2) return 'A pipe joins two different houses.';
    if (cost < 0 || cost > 100000) return 'Each pipe cost is between 0 and 100000.';
  }
  return null;
}

