function minCostToSupplyWater(n, wells, pipes) {
  // Prim's algorithm on a dense matrix, with node 0 standing for "the ground water".
  const size = n + 1;
  const weight = Array.from({ length: size }, () => new Array(size).fill(Infinity));
  for (let i = 1; i <= n; i++) weight[0][i] = weight[i][0] = wells[i - 1];
  for (const [a, b, c] of pipes) if (c < weight[a][b]) weight[a][b] = weight[b][a] = c;
  const inTree = new Array(size).fill(false);
  const dist = new Array(size).fill(Infinity);
  dist[0] = 0;
  let sum = 0;
  for (let step = 0; step < size; step++) {
    let u = -1;
    for (let v = 0; v < size; v++) if (!inTree[v] && (u === -1 || dist[v] < dist[u])) u = v;
    inTree[u] = true;
    sum += dist[u];
    for (let v = 0; v < size; v++) if (!inTree[v] && weight[u][v] < dist[v]) dist[v] = weight[u][v];
  }
  return sum;
}

