function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(500, 2000) : pick(2, 6);
  const top = large ? 100000 : pick(1, 12);
  const wells = Array.from({ length: n }, () => (rand() < 0.1 ? 0 : pick(0, top)));
  const count = large ? 2000 : pick(1, 8);
  const pipes = [];
  for (let j = 0; j < count; j++) {
    const house1 = pick(1, n);
    let house2 = pick(1, n - 1);
    if (house2 >= house1) house2++;
    // Pipes tend to be cheaper than wells so both kinds of choice matter.
    pipes.push([house1, house2, pick(0, Math.floor(top * (0.2 + rand() * 0.8)))]);
  }
  return [n, wells, pipes];
}
